create extension if not exists pgcrypto;create table if not exists public.families(id text primary key,created_at timestamptz default now());create table if not exists public.feedings(id uuid primary key,family_id text not null references public.families(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,event_time timestamptz not null,type text not null check(type in ('left','right','formula')),minutes integer default 0,ml integer default 0,created_at timestamptz default now());create table if not exists public.diapers(id uuid primary key,family_id text not null references public.families(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,event_time timestamptz not null,type text not null check(type in ('pee','poop','diaper')),created_at timestamptz default now());alter table public.families enable row level security;alter table public.feedings enable row level security;alter table public.diapers enable row level security;create policy "auth families" on public.families for all to authenticated using(true) with check(true);create policy "auth feedings" on public.feedings for all to authenticated using(true) with check(true);create policy "auth diapers" on public.diapers for all to authenticated using(true) with check(true);insert into public.families(id) values('TUANTUAN-2026') on conflict do nothing;